/**
 * The Metro bundle budget for the React Native packages. Metro does not tree-shake, so what an app
 * pays for @libo11y/react-native is every module it reaches. This reads the source map of the
 * fixture Expo app's Android bundle (exported without Hermes bytecode, so the map's generated
 * positions are JavaScript), attributes every generated byte to the source its segment names, sums
 * the bytes of the sources inside node_modules/@libo11y/ and node_modules/@opentelemetry/, and
 * checks them against ts/rn-bundle-budget.json. It also fails when one of those packages is bundled
 * twice, from two installed copies or from both its CommonJS and its ESM build, because two copies
 * of an OpenTelemetry package keep two sets of globals.
 *
 *   bun scripts/rn-bundle-size.ts --map FILE --bundle FILE [--budget FILE] [--check] [--summary FILE]
 *
 * prints a markdown table, appends it to --summary (CI passes $GITHUB_STEP_SUMMARY), and exits 1
 * under --check when a group is over its budget or a package is bundled twice. A budget increase is
 * a reviewed diff of rn-bundle-budget.json, with the measured number in the commit message.
 */
import { appendFileSync, readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * The parts of a version 3 source map this reads: a plain map, or an index map of sections, each a
 * plain map placed at an offset, as Metro writes one section per module.
 */
export interface SourceMap {
  readonly version: number;
  readonly sources?: readonly (string | null)[];
  readonly sourceRoot?: string;
  readonly mappings?: string;
  readonly sections?: readonly {
    readonly offset: { readonly line: number; readonly column: number };
    readonly map: SourceMap;
  }[];
}

/** The rn-bundle-budget.json format: the most bytes each group may add to the bundle. */
export interface BudgetFile {
  readonly unit: string;
  readonly budgets: Readonly<Record<string, number>>;
}

/** Where the generated bytes of a bundle come from. */
export interface Attribution {
  /** UTF-8 bytes per source, sourceRoot included. */
  readonly bySource: ReadonlyMap<string, number>;
  /** Bytes before a line's first segment or under a segment with no source. */
  readonly unmapped: number;
  /** Every byte of the bundle. */
  readonly total: number;
}

const B64: ReadonlyMap<string, number> = new Map(
  [..."ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"].map((c, i) => [c, i]),
);

/** The values of one segment, decoded from base64 VLQ. */
function decodeSegment(segment: string): number[] {
  const values: number[] = [];
  let value = 0;
  let shift = 0;
  for (const ch of segment) {
    const digit = B64.get(ch);
    if (digit === undefined)
      throw new Error(`rn-bundle-size: bad base64 VLQ character ${JSON.stringify(ch)}`);
    value += (digit & 31) * 2 ** shift;
    if (digit & 32) {
      shift += 5;
      continue;
    }
    values.push(value % 2 === 1 ? -Math.floor(value / 2) : value / 2);
    value = 0;
    shift = 0;
  }
  if (shift !== 0) throw new Error("rn-bundle-size: a segment ends inside a VLQ value");
  return values;
}

const encoder = new TextEncoder();

/** A decoded segment: its generated column and the source it names, if any. */
interface Segment {
  readonly column: number;
  readonly source: string | undefined;
}

/**
 * Adds the segments of a plain map placed at (line, column) to lines, by generated line. The
 * column offset applies to the map's first line only, as the index map format defines it.
 */
function collect(map: SourceMap, line: number, column: number, lines: Map<number, Segment[]>): void {
  if (map.sections !== undefined) throw new Error("rn-bundle-size: nested index maps are not supported");
  const root = map.sourceRoot ?? "";
  const names = (map.sources ?? []).map((s) => (s === null ? undefined : `${root}${s}`));
  let sourceIndex = 0;
  for (const [i, text] of (map.mappings ?? "").split(";").entries()) {
    let col = i === 0 ? column : 0;
    const out = lines.get(line + i) ?? [];
    for (const raw of text.split(",")) {
      if (raw === "") continue;
      const v = decodeSegment(raw);
      col += v[0] ?? 0;
      let source: string | undefined;
      if (v.length >= 4) {
        sourceIndex += v[1] ?? 0;
        source = names[sourceIndex];
      }
      out.push({ column: col, source });
    }
    if (out.length > 0) lines.set(line + i, out);
  }
}

/**
 * Attributes every byte of code to a source of map. A segment's bytes run from its column to the
 * next segment's column, or to the end of its line; a line's newline counts for its last segment.
 * Bytes before a line's first segment, and under a segment with no source, are unmapped. Columns
 * are UTF-16 code units, as the format defines them; the counts are UTF-8 bytes.
 */
export function attribute(code: string, map: SourceMap): Attribution {
  const segmentsByLine = new Map<number, Segment[]>();
  if (map.sections === undefined) collect(map, 0, 0, segmentsByLine);
  else for (const s of map.sections) collect(s.map, s.offset.line, s.offset.column, segmentsByLine);

  const bySource = new Map<string, number>();
  let unmapped = 0;
  const add = (source: string | undefined, text: string): void => {
    const n = encoder.encode(text).length;
    if (n === 0) return;
    if (source === undefined) unmapped += n;
    else bySource.set(source, (bySource.get(source) ?? 0) + n);
  };
  const lines = code.split("\n");
  for (const [i, line] of lines.entries()) {
    const newline = i < lines.length - 1 ? "\n" : "";
    const segments = (segmentsByLine.get(i) ?? []).sort((a, b) => a.column - b.column);
    add(undefined, line.slice(0, segments[0]?.column ?? line.length));
    for (const [j, s] of segments.entries()) {
      const end = segments[j + 1]?.column ?? line.length;
      add(s.source, line.slice(s.column, end) + (j === segments.length - 1 ? newline : ""));
    }
    if (segments.length === 0) add(undefined, newline);
  }
  return { bySource, unmapped, total: encoder.encode(code).length };
}

/** The bytes of the sources inside node_modules/<group>/ for each group, such as "@libo11y". */
export function groupSums(
  bySource: ReadonlyMap<string, number>,
  groups: readonly string[],
): Record<string, number> {
  const sums: Record<string, number> = Object.fromEntries(groups.map((g) => [g, 0]));
  for (const [source, bytes] of bySource) {
    for (const g of groups) if (source.includes(`node_modules/${g}/`)) sums[g] = (sums[g] ?? 0) + bytes;
  }
  return sums;
}

/** The installed directory and the name of the package a source belongs to, from its last node_modules. */
function packageOf(source: string): { dir: string; name: string } | undefined {
  const at = source.lastIndexOf("node_modules/");
  if (at < 0) return undefined;
  const parts = source.slice(at + "node_modules/".length).split("/");
  const name = parts[0]?.startsWith("@") ? `${parts[0]}/${parts[1] ?? ""}` : (parts[0] ?? "");
  return { dir: source.slice(0, at + "node_modules/".length) + name, name };
}

/**
 * The packages, by name and sorted, that sources reach from more than one installed copy, or from
 * both their CommonJS (.cjs) and their ESM (.mjs) build in one copy.
 */
export function duplicatePackages(sources: Iterable<string>): string[] {
  const copies = new Map<string, Map<string, Set<string>>>();
  for (const source of sources) {
    const p = packageOf(source);
    if (p === undefined) continue;
    const format = source.endsWith(".cjs") ? "cjs" : source.endsWith(".mjs") ? "mjs" : "js";
    const dirs = copies.get(p.name) ?? new Map<string, Set<string>>();
    copies.set(p.name, dirs);
    const formats = dirs.get(p.dir) ?? new Set<string>();
    dirs.set(p.dir, formats);
    formats.add(format);
  }
  return [...copies]
    .filter(([, dirs]) => dirs.size > 1 || [...dirs.values()].some((f) => f.has("cjs") && f.has("mjs")))
    .map(([name]) => name)
    .sort();
}

/** One group's row. */
export interface GroupRow {
  readonly group: string;
  readonly bytes: number;
  readonly budget: number;
  readonly over: boolean;
}

export function formatTable(rows: readonly GroupRow[], duplicates: readonly string[]): string {
  const lines = [
    "| Group | Bytes | Budget | Status |",
    "|---|---|---|---|",
    ...rows.map((r) => `| ${r.group} | ${r.bytes} | ${r.budget} | ${r.over ? "over" : "ok"} |`),
  ];
  if (duplicates.length > 0) lines.push("", `Bundled twice: ${duplicates.join(", ")}`);
  return lines.join("\n");
}

function flag(args: readonly string[], name: string): string | undefined {
  const i = args.indexOf(name);
  return i < 0 ? undefined : args[i + 1];
}

export function main(args: readonly string[]): number {
  const mapFile = flag(args, "--map");
  const bundleFile = flag(args, "--bundle");
  if (mapFile === undefined || bundleFile === undefined) {
    console.error(
      "usage: rn-bundle-size.ts --map FILE --bundle FILE [--budget FILE] [--check] [--summary FILE]",
    );
    return 2;
  }
  const budgetFile = flag(args, "--budget") ?? join(import.meta.dirname, "..", "rn-bundle-budget.json");
  const budget = JSON.parse(readFileSync(budgetFile, "utf8")) as BudgetFile;
  const map = JSON.parse(readFileSync(mapFile, "utf8")) as SourceMap;
  const a = attribute(readFileSync(bundleFile, "utf8"), map);
  const groups = Object.keys(budget.budgets);
  const sums = groupSums(a.bySource, groups);
  const rows = groups.map((group) => {
    const bytes = sums[group] ?? 0;
    const limit = budget.budgets[group] ?? 0;
    return { group, bytes, budget: limit, over: bytes > limit };
  });
  const duplicates = duplicatePackages(
    [...a.bySource.keys()].filter((s) => groups.some((g) => s.includes(`node_modules/${g}/`))),
  );
  const table = formatTable(rows, duplicates);
  console.log(`${table}\n\n${budget.unit}; the whole bundle is ${a.total} bytes.`);
  const summary = flag(args, "--summary");
  if (summary !== undefined) appendFileSync(summary, `### React Native bundle budget\n\n${table}\n`);
  const failed = rows.some((r) => r.over) || duplicates.length > 0;
  return args.includes("--check") && failed ? 1 : 0;
}

if (import.meta.main) process.exitCode = main(process.argv.slice(2));
